#!/usr/bin/env python3
"""Step selection for `tools/check-all.sh --quick`, table-driven from tools/gate-manifest.json (generated by tools/gate-manifest, PLAN-GATE-2X D2).
Usage: gate_select.py STAMP_FILE   -> stdout: the steps to run (space separated), or FULL when there is no usable base (worktree stamp or host registry
                                      $GATE_PASS_DIR, default ~/.cache/pixelios/gate-pass); stderr: `gate: skipped STEP: ...` per skipped step and
                                      `gate: FULL, unresolved: FILE` (then every step is printed: a file no manifest row accounts for runs the full gate)
       gate_select.py --explain FILE...   no git, no stamp: `gate: ran|skipped STEP: why` per step, then RESULT: PASS gate_select ran=N skipped=M
       gate_select.py --state"""
import fnmatch, hashlib, json, os, pathlib, re, subprocess, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))   # python3 -I does not put the script directory on the path
import unit_select

REPO = pathlib.Path(__file__).resolve().parent.parent
CHECK_ALL = REPO / "tools" / "check-all.sh"            # its ALL is the list of steps; the manifest must hold exactly one row per step (drift() below)
BASE = None                                             # the commit the quick gate diffs against (set by __main__): a deleted/edited patch is also judged by its content there
MANIFEST_PATH = REPO / "tools" / "gate-manifest.json"   # generated by tools/gate-manifest --write (PLAN-GATE-2X D2); this module only READS it


def load_manifest(path=None):
    """The step table. A missing or unreadable manifest is a loud error (gate_select exits 1, check-all.sh prints GATE FAIL gate_select), never a silent full/empty selection."""
    with open(path or MANIFEST_PATH) as fh:
        return json.load(fh)


MANIFEST = load_manifest()
ALL = [r["step"] for r in MANIFEST["steps"]]
SHIM = ["build", "host-tests", "boot-safety"]      # what a shim/ change selects in the quick lane (L1: ONE shim build); the 11 variant builds are class formal (PLAN-GATE-LAYERS s.2)
VARIANT_BUILDS = [r["step"] for r in MANIFEST["steps"] if r["step"].startswith("build-")]
WLAN_MUT_INPUTS = tuple(sorted(e for e in next(r for r in MANIFEST["steps"] if r["step"] == "wlan-mutants")["inputs"] if isinstance(e, str) and "*" not in e))


def is_shell(f):
    """Same rule as tools/shell-files: *.sh or a sh/bash/dash shebang on line 1 (the file may be gone: deleted files select nothing)."""
    if f.endswith(".sh"):
        return True
    try:
        with open(REPO / f, "rb") as fh:
            first = fh.readline(80)
    except OSError:   # lint-silent: expected a file deleted in the work tree has no shebang line: not a shell script
        return False
    return re.match(rb"#!\s*(/usr/bin/env\s+)?(/[a-z/]*/)?(ba|da)?sh(\s|$)", first) is not None


def entry_match(e, f):
    """Input entry E of a manifest row: a glob, or {"glob": G, "except": [..]}. Returns the glob that matched, else None."""
    if isinstance(e, dict):
        return e["glob"] if fnmatch.fnmatchcase(f, e["glob"]) and not any(fnmatch.fnmatchcase(f, x) for x in e.get("except", [])) else None
    return e if e != "*" and fnmatch.fnmatchcase(f, e) else None


def patch_edits(f, prefixes):
    """A patch file (xnu/patches/NNNN-*.patch, read from disk now: the static manifest cannot know a patch added after `gate-manifest --write`) that edits a file under one of PREFIXES
    (`--- a/<prefix>*` / `+++ b/<prefix>*`): the chip-writer sources the wlan mutant test rebuilds (review gate-runfast-1 C2)."""
    if not (f.startswith("xnu/patches/") and f.endswith(".patch")):
        return None
    texts = []
    try:
        texts.append((REPO / f).read_text(errors="replace"))
    except OSError:   # lint-silent: expected deleted in the work tree: judged by its content at BASE below
        pass      # deleted in the work tree: judged by its content at BASE below (review gate-2x-s2-r1 F3)
    if BASE:      # a patch that dropped its wlan hunk, or is gone, still changes what was tested
        r = subprocess.run(["git", "-C", str(REPO), "show", "%s:%s" % (BASE, f)], capture_output=True, text=True, errors="replace")
        if r.returncode == 0:
            texts.append(r.stdout)
    for pre in prefixes:
        if any(re.search(r"^(\+\+\+|---) [ab]/%s" % re.escape(pre), x, re.M) for x in texts):
            return "patch edits %s*" % pre
    return None


def row_match(row, f):
    """Why this changed file F is an input of the row: the matching glob (or `shell file`), else None. Rows whose inputs are ["*"] (every change) are not matched here."""
    for e in row.get("inputs", []):
        g = entry_match(e, f)
        if g:
            return g
    if row.get("predicate") == "shell" and is_shell(f):
        return "shell file"
    return patch_edits(f, row["patch_edits"]) if row.get("patch_edits") else None


def unresolved(files, m):
    """Changed files that no row input, predicate or `inert` glob accounts for (rule 8: these select FULL, loudly)."""
    rows = [r for r in m["steps"] if r["inputs"] != ["*"]]
    return [f for f in files if not any(row_match(r, f) for r in rows) and not any(fnmatch.fnmatchcase(f, g) for g in m["inert"])]


def decide(files, m=None):
    """(steps in ALL order, {step: reason}) for this list of changed paths. validate/rules/public-split (inputs ["*"]) run for every change; the other
    rows by their inputs; `follows` rows with the steps they follow; the completes_full steps once every other step is selected (a run that selected
    everything counts as a full one)."""
    m = m or MANIFEST
    rows = m["steps"]
    why = {}
    for f in files:       # the selector's own inputs changed: the FULL set (PLAN-GATE-LAYERS s.3 last row)
        g = next((g for g in m.get("selector_inputs", []) if fnmatch.fnmatchcase(f, g)), None)
        if g:
            return [r["step"] for r in rows], {r["step"]: "%s matches selector input %s: full set" % (f, g) for r in rows}
    for r in rows:
        if r["inputs"] == ["*"]:
            why[r["step"]] = "every change"
            continue
        if r.get("class") == "formal":      # formal rows are never selected by their inputs in a quick run; they only complete a full one (below)
            continue
        for f in files:
            g = row_match(r, f)
            if g:
                why.setdefault(r["step"], "%s matches %s" % (f, g))
    for r in rows:
        fol = [s for s in r.get("follows", []) if s in why]
        if fol and r["step"] not in why:
            why[r["step"]] = "follows %s" % fol[0]
    cf = set(m["completes_full"]) | {r["step"] for r in rows if r.get("class") == "formal"}
    if all(r["step"] in why for r in rows if r["step"] not in cf):
        for s in cf:
            why.setdefault(s, "every other step is selected: counts as a full run")
    return [r["step"] for r in rows if r["step"] in why], why


def drift(m):
    """(steps that differ, every step either side names): a step of check-all.sh ALL with no manifest row, a row that is not in ALL, or an unreadable ALL
    (review gate-2x-s2-r1 F7: such a step would be neither run nor listed as skipped). The rows are the manifest's, ALL is read from check-all.sh now."""
    rows = [r["step"] for r in m["steps"]]
    try:
        mm = re.search(r'^ALL="([^"]*)"', CHECK_ALL.read_text(), re.M)
    except OSError:   # lint-silent: expected an unreadable check-all.sh makes mm None, reported right below as `ALL unreadable`
        mm = None
    if not mm:
        return ["%s ALL unreadable" % CHECK_ALL.name], rows
    ca = mm.group(1).split()
    return [s for s in ca if s not in rows] + [s for s in rows if s not in ca], ca + [s for s in rows if s not in ca]


def select(files, manifest=None):
    """Steps to run; every step (FULL, rule 8) when a changed file is unresolved (no row, predicate or `inert` glob accounts for it) or the manifest drifts from check-all.sh ALL."""
    m = manifest or MANIFEST
    bad, every = drift(m)
    if bad or unresolved(files, m):
        return every
    return decide(files, m)[0]


def explain(files, m=None):
    """One `gate: ran|skipped` line per step (the loud-skip contract, rule 8) and the counts."""
    m = m or MANIFEST
    steps, why = decide(files, m)
    lines = []
    bad, every = drift(m)
    if bad:
        return ["gate: MANIFEST DRIFT: %s" % s for s in bad] + ["gate: ran %s: manifest drift selects FULL" % s for s in every], len(every), 0
    un = unresolved(files, m)
    if un:
        return ["gate: FULL, unresolved: %s" % f for f in un] + ["gate: ran %s: unresolved file selects FULL" % r["step"] for r in m["steps"]], len(m["steps"]), 0
    for r in m["steps"]:
        s = r["step"]
        if s in why:
            lines.append("gate: ran %s: %s" % (s, why[s]))
        else:
            lines.append("gate: skipped %s: no input changed (%s)" % (s, skip_row(r)))
    return lines, len(steps), len(m["steps"]) - len(steps)


def skip_row(r):
    """The manifest row, in words, for the skip line."""
    ins = r.get("inputs") or []
    shown = [e["glob"] if isinstance(e, dict) else e for e in ins]
    head = ", ".join(shown[:3]) + (", ... +%d" % (len(shown) - 3) if len(shown) > 3 else "")
    if r.get("predicate"):
        head = (head + ", " if head else "") + "%s files" % r["predicate"]
    if r.get("follows"):
        head = (head + ", " if head else "") + "follows %d steps" % len(r["follows"])
    return "row %s lane %s class %s inputs: %s" % (r["step"], r["lane"], r["class"], head or "none (full gate only)")


def git(*a):
    return subprocess.run(["git", *a], capture_output=True, text=True)


MUTANT_STEPS = ("wlan-mutants",)


CLASSIFIER_FILES = ("tools/change-class", "tools/change_class_selftest_lib.py", "tools/gate_select.py", "tools/gate-manifest.json", "tools/unit_select.py")   # unit_select: imported here
SKIP_CLASSES = ("log-only", "log-read")   # log-read skips mutants but keeps the Opus review (tools/change-class docstring)


def class_split(steps, lines, base):
    """T-8fe9 M2 (user 2026-11-03, RULES R31): a quick gate whose diff tools/change-class classes log-only or log-read skips the mutant lane;
    hw-write, tools, a branch that changes the classifier or this split (it would judge itself), or any classifier error or timeout keep it
    (fail closed). The boot-safety audit is never dropped here."""
    if not any(s in steps for s in MUTANT_STEPS) or os.environ.get("GATE_CLASS_SPLIT") == "0":
        return steps, lines
    ch = changed(base)   # a tools/<stdlib name>.py would shadow the stdlib in tools/ scripts (Opus r2 f8); the classifier runs with -I as well
    own = sorted(set(ch) & set(CLASSIFIER_FILES) | {f for f in ch if re.match(r"^tools/(\w+)\.py$", f) and f[6:-3] in sys.stdlib_module_names})
    if own:
        return steps, lines + ["gate: class ERROR: classifier changed on this branch (%s): mutant lane kept" % ",".join(own)]
    try:
        r = subprocess.run([sys.executable, "-I", str(REPO / "tools" / "change-class"), "--base", base], capture_output=True, cwd=str(REPO), timeout=120)
    except subprocess.TimeoutExpired:
        return steps, lines + ["gate: class ERROR: timeout: mutant lane kept (tools/change-class ran > 120 s)"]
    out = r.stdout.decode("utf-8", "replace").split("\n")   # bytes, one line end: only the tool's own last line counts, never quoted diff text (Opus r6 f2)
    m = re.fullmatch(r"RESULT: PASS change-class class=(\S+) files=\d+ port_lines=\d+ base=\S+", out[-2] if len(out) > 1 else "")
    cls = m.group(1) if m and r.returncode == 0 else None
    if cls not in SKIP_CLASSES:
        return steps, lines + ["gate: class %s: mutant lane kept (%s)" % (cls or "ERROR", "tools/change-class rc=%d" % r.returncode if cls is None else "not log-only")]
    return [s for s in steps if s not in MUTANT_STEPS], lines + ["gate: skipped %s: change class %s (tools/change-class, RULES R31)" % (s, cls) for s in steps if s in MUTANT_STEPS]


def usable(base):
    return bool(base) and git("cat-file", "-e", base + "^{commit}").returncode == 0 and \
        git("merge-base", "--is-ancestor", base, "HEAD").returncode == 0


def base_from_stamp(path):
    try:
        base = open(path).read().strip()
    except OSError:   # lint-silent: expected a missing or unreadable base file means no usable base: None
        return None
    return base if usable(base) else None


def pass_dir():
    return pathlib.Path(os.environ.get("GATE_PASS_DIR") or pathlib.Path.home() / ".cache" / "pixelios" / "gate-pass")


def tree_state():
    """(g, a) of this tree (research 69): g = sha256 over the relative names + contents of tools/third_party (else the main clone's, as shim/build.sh:95-97), a = 1 when research/ipsw-x/d22ap.adt exists (the mkadt identity test is skipped without it)."""
    tp = REPO / "tools" / "third_party"
    if not (tp / "mkbootimg.py").exists():
        tp = pathlib.Path(git("rev-parse", "--path-format=absolute", "--git-common-dir").stdout.strip()).parent / "tools" / "third_party"
    h = hashlib.sha256()
    # __pycache__/*.pyc are skipped like tools/gate-identity does: their bytes differ per checkout (embedded source path), which gave every checkout its own g and made quick gates run full
    for f in sorted(x for x in tp.rglob("*") if x.is_file() and not ("__pycache__" in x.parts and x.suffix == ".pyc")):
        h.update(f.relative_to(tp).as_posix().encode() + b"\0" + f.read_bytes() + b"\0")
    return h.hexdigest(), int((REPO / "research" / "ipsw-x" / "d22ap.adt").exists())


def registry_bases(limit=40):
    """Commits that passed a FULL gate anywhere on this host (check-all.sh writes <sha> with the blob id of its own script on a clean full PASS).
    Entry = "<blob> <g> <a>" (research 69). Ignored: another check-all.sh blob, another g, a=0 when this tree has a=1 (an a=1 entry satisfies an a=0 tree), legacy 1-field entries, non-ancestors of HEAD. Newest `limit` entries only."""
    cg, ca = tree_state()
    blob = git("hash-object", "tools/check-all.sh").stdout.strip()
    try:
        ents = sorted(pass_dir().iterdir(), key=lambda p: p.stat().st_mtime, reverse=True)
    except OSError:   # lint-silent: expected a missing pass dir (never gated) means no passing sha: []
        return []
    out = []
    for p in ents:
        try:
            f = p.read_text().split()
            ok = re.fullmatch(r"[0-9a-f]{40}", p.name) and len(f) == 3 and f[0] == blob and f[1] == cg and f[2] in "01" and int(f[2]) >= ca
        except OSError:   # lint-silent: expected an entry that vanished or is unreadable is not a pass record: next one
            continue
        if ok and usable(p.name):
            out.append(p.name)
        if len(out) >= limit:
            break
    return out


def best_base(stamp_path):
    """The nearest commit that passed a full gate: the worktree's own stamp or a host-wide registry entry, whichever leaves the fewest changed files."""
    cands = [b for b in [base_from_stamp(stamp_path)] + registry_bases() if b]
    return min(cands, key=lambda b: len(changed(b)), default=None)


def changed(base):
    tracked = git("diff", "--name-only", "--no-renames", base).stdout.split()
    new = git("ls-files", "--others", "--exclude-standard").stdout.split()
    return tracked + new


if __name__ == "__main__":
    if sys.argv[1:] == ["--state"]:
        print(*tree_state())
        sys.exit(0)
    if sys.argv[1:2] == ["--explain"]:   # no git, no stamp: what a change to these files would run and skip (PLAN-GATE-2X D6)
        lines, ran, skipped = explain(sys.argv[2:])
        if any(l.startswith("gate: ran unit:") for l in lines):
            lines += unit_select.select_tests(sys.argv[2:])[1]   # S4: which test files the unit step runs (last line: ran N of M)
        print("\n".join(lines))
        print("RESULT: PASS gate_select ran=%d skipped=%d" % (ran, skipped))
        sys.exit(0)
    if len(sys.argv) != 2:
        print("usage: gate_select.py STAMP_FILE | --state | --explain FILE...", file=sys.stderr)
        sys.exit(2)
    b = best_base(sys.argv[1])
    BASE = b
    if b is None:
        print("FULL")
        sys.exit(0)
    files = changed(b)
    lines, ran, skipped = explain(files)
    # stderr: the unresolved files and one line per skipped step (check-all.sh --quick copies them into its log); stdout: the steps (or FULL)
    steps = select(files)
    if "unit" in steps and not any(l.startswith(("gate: FULL", "gate: MANIFEST")) for l in lines):
        # S4: the unit step of this quick gate runs the selected test files only (tools/gate-unit-shards --selected, passed by check-all.sh --quick only, reads GATE_UNIT_ONLY=<this file>; absent = all)
        sel, ulines, total = unit_select.select_tests(files)
        lines += ulines
        if len(sel) < total:
            out = REPO / "shim" / "out" / "gate" / "unit-only.txt"
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_text("".join(t + "\n" for t in sel))
    steps, lines = class_split(steps, lines, b)
    print("\n".join(l for l in lines if l.startswith(("gate: skipped", "gate: FULL", "gate: MANIFEST", "gate: unit", "gate: class"))), file=sys.stderr)
    print(" ".join(steps))
